<script setup lang="ts">
import {ref,computed,nextTick,onMounted,onBeforeUnmount,watch} from 'vue';
import {request,ApiError} from '../lib/api';
import {workDateParts} from '../lib/work-tasks';
import {shiftDay} from '../lib/work-calendar';
import WorkDatePicker from './WorkDatePicker.vue';
import {activities,foods,dayReport,entryRemark,bmi,bmiLabel,foodCalories,exerciseCalories,weightDays,type SlimEntry} from '../lib/slim';
const activityCards=[{icon:'🚶',title:'散步摸鱼',detail:'平地走路 · 约4.5–5公里/小时'},{icon:'👟',title:'快走放风',detail:'平地快走 · 约5.6–6.3公里/小时'},{icon:'🏃',title:'慢跑清空脑袋',detail:'自选配速 · 按实际体感活动'},{icon:'🚲',title:'骑车兜个风',detail:'休闲骑行 · 低于16公里/小时'},{icon:'🌿',title:'伸个懒腰',detail:'轻度拉伸 · 给身体松松绑'}];
const props=defineProps<{foreground:boolean}>();
const emit=defineEmits<{(e:'auth-expired'):void}>();
const today=()=>workDateParts(new Date().toISOString()).day;
const day=ref(today()),entries=ref<SlimEntry[]>([]),gender=ref('male'),height=ref(''),bodyWeight=ref('');
const kind=ref<'food'|'exercise'|'weight'>('food'),name=ref(''),grams=ref('100'),rate=ref(''),minutes=ref('30'),activity=ref(0),query=ref('');
const error=ref(''),busy=ref(false),loading=ref(false),loaded=ref(false),message=ref(''),page=ref(1);
let disposed=false,seq=0,pendingID='';
const catalog=computed(()=>foods.filter(f=>f.name.includes(query.value.trim())));
const selected=computed(()=>entries.value.filter(e=>e.day===day.value));
const intake=computed(()=>selected.value.filter(e=>e.kind==='food').reduce((s,e)=>s+e.calories,0));
const burn=computed(()=>selected.value.filter(e=>e.kind==='exercise').reduce((s,e)=>s+e.calories,0));
const duration=computed(()=>selected.value.filter(e=>e.kind==='exercise').reduce((s,e)=>s+e.quantity,0));
const weights=computed(()=>weightDays(entries.value));
const recentWeights=computed(()=>weights.value.slice(-14));
const change=computed(()=>weights.value.length>1?weights.value[weights.value.length-1].weight-weights.value[0].weight:null);
const weightKg=computed(()=>Number(bodyWeight.value)/2);
const bmiValue=computed(()=>bmi(Number(height.value),weightKg.value));
const preview=computed(()=>kind.value==='food'?foodCalories(Number(grams.value),Number(rate.value)):exerciseCalories(Number(minutes.value),weightKg.value,activities[activity.value].met));
const report=computed(()=>dayReport(selected.value));
const fortune=ref(0),celebrate=ref(false);
const fortunes=['老板的饼是零卡的，因为根本吃不到。','脑子可以下线，午饭不能缺席。','今天不卷腹，也不卷同事。','热量有单位，快乐暂时没有。','饭要趁热吃，消息可以放凉了回。','身体是自己的，工位是公司的。'];
const week=computed(()=>Array.from({length:7},(_,i)=>{const date=shiftDay(today(),i-6);const list=entries.value.filter(e=>e.day===date);return {date,caption:i===6?'今天':date.slice(5),count:list.length,stamps:dayReport(list).stamps};}));
let celebrationTimer:ReturnType<typeof setTimeout>|undefined;
function jumpTo(next:'food'|'exercise'|'weight'){kind.value=next;
 // #ifdef H5
 if(typeof document!=='undefined')document.getElementById('slim-journal')?.scrollIntoView({behavior:'smooth',block:'start'});
 // #endif
}
function repeat(e:SlimEntry){if(busy.value)return;day.value=today();kind.value=e.kind;if(e.kind==='food'){name.value=e.name;grams.value=String(e.quantity);rate.value=String(e.rate);}else if(e.kind==='exercise'){activity.value=Math.max(0,activities.findIndex(x=>x.name===e.name));minutes.value=String(e.quantity);}jumpTo(e.kind);message.value='同款已填好，份量和时长确认后再保存，不自动记账。';}
const latestWeight=computed(()=>weights.value.length?weights.value[weights.value.length-1]:null);
function useLatestWeight(){if(latestWeight.value)bodyWeight.value=String(latestWeight.value.weight*2);}
const shown=computed(()=>selected.value.slice(0,page.value*20));
function fail(e:unknown){if(disposed)return;if(e instanceof ApiError&&e.status===401)emit('auth-expired');if(!(e instanceof ApiError&&e.status===0))error.value=(e as Error).message;}
async function load(){if(busy.value)return;const n=++seq;loading.value=true;error.value='';try{const d=await request<{profile:{gender:string;height:number};entries:SlimEntry[]}>('/slim');if(disposed||n!==seq)return;entries.value=d.entries;if(!loaded.value){gender.value=d.profile.gender||'male';height.value=d.profile.height?String(d.profile.height):'';const w=weightDays(d.entries);bodyWeight.value=w.length?String(w[w.length-1].weight*2):'';loaded.value=true;}}catch(e){fail(e);}finally{if(!disposed&&n===seq)loading.value=false;}}
function pickFood(f:typeof foods[number]){name.value=f.name;rate.value=String(f.kcal);}
watch([kind,day,name,grams,rate,minutes,activity,bodyWeight],()=>{pendingID='';message.value='';},{flush:'sync'});
watch(day,()=>{page.value=1;celebrate.value=false;});
async function saveProfile(){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await request('/slim/profile','POST',{gender:gender.value,height:Number(height.value)});if(!disposed)message.value='档案存好了，身体不参加绩效考核。';}catch(e){fail(e);}finally{if(!disposed)busy.value=false;}}
async function save(){if(busy.value||!loaded.value)return;error.value='';message.value='';if(!day.value){error.value='先选记录日期。';return;}if(kind.value==='food'&&(!name.value.trim()||!rate.value.trim()||!grams.value.trim())){error.value='填写食物、克数和每100克热量。';return;}if(kind.value!=='food'&&!bodyWeight.value.trim()){error.value='先填写下方的体重（斤），运动估算也需要它。';return;}
 busy.value=true;seq++;loading.value=false;pendingID=pendingID||('slim_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2));
 try{const e=await request<SlimEntry>('/slim/entries','POST',{id:pendingID,day:day.value,kind:kind.value,name:kind.value==='food'?name.value:kind.value==='weight'?'体重打卡':activities[activity.value].name,quantity:Number(kind.value==='food'?grams.value:minutes.value),rate:Number(rate.value),weight:weightKg.value});if(disposed)return;entries.value=[e,...entries.value.filter(x=>x.id!==e.id)].sort((a,b)=>b.day.localeCompare(a.day));pendingID='';message.value=e.name+' · '+entryRemark(e);fortune.value=(fortune.value+1)%fortunes.length;celebrate.value=true;clearTimeout(celebrationTimer);celebrationTimer=setTimeout(()=>{celebrate.value=false;},900);}catch(e){fail(e);}finally{if(!disposed)busy.value=false;}}
const deleting=ref<SlimEntry|null>(null),deleteError=ref('');
let deleteFocus:HTMLElement|null=null,previousOverflow='';
function restoreDeleteFocus(){
 // #ifdef H5
 if(typeof document!=='undefined'){document.body.style.overflow=previousOverflow;deleteFocus?.focus();deleteFocus=null;}
 // #endif
}
function remove(e:SlimEntry){if(busy.value||deleting.value)return;deleteError.value='';deleting.value=e;
 // #ifdef H5
 if(typeof document!=='undefined'){deleteFocus=document.activeElement as HTMLElement;previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';nextTick(()=>document.getElementById('slim-delete-cancel')?.focus());}
 // #endif
}
function cancelDelete(){if(busy.value)return;deleting.value=null;deleteError.value='';restoreDeleteFocus();}
function deleteKeys(e:KeyboardEvent){if(e.key==='Escape'){e.preventDefault();cancelDelete();}if(e.key==='Tab'){
 // #ifdef H5
 if(typeof document!=='undefined'){const buttons=Array.from(document.getElementById('slim-delete-dialog')?.querySelectorAll<HTMLButtonElement>('button:not([disabled])')||[]);const first=buttons[0],last=buttons[buttons.length-1];if(!first){e.preventDefault();return;}if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
 // #endif
}}
async function confirmDelete(){if(!deleting.value||busy.value||disposed)return;const id=deleting.value.id;busy.value=true;seq++;deleteError.value='';try{await request('/slim/entries/'+id+'/delete','POST',{});if(!disposed){entries.value=entries.value.filter(x=>x.id!==id);deleting.value=null;restoreDeleteFocus();}}catch(err){if(!disposed){deleteError.value=(err as Error).message;fail(err);}}finally{if(!disposed)busy.value=false;}}
function barHeight(w:number){const all=recentWeights.value.map(e=>e.weight),low=Math.min(...all),high=Math.max(...all);return (high===low?45:20+(w-low)/(high-low)*55)+'px';}
watch(()=>props.foreground,v=>{if(v)load();else if(deleting.value&&!busy.value)cancelDelete();});onMounted(load);onBeforeUnmount(()=>{disposed=true;seq++;clearTimeout(celebrationTimer);if(deleting.value)restoreDeleteFocus();});
</script>
<template>
<view class="slim-lab">
 <view class="hero"><view><text class="eyebrow">BODY / 牛马身体观察站</text><text class="title">瘦瘦研究所</text><text class="subtitle">老板的饼不计入热量，自己的饭要好好吃。</text></view><view class="stamp">认真吃饭<text>合理摸鱼</text></view></view>
 <view class="date-line"><WorkDatePicker v-model="day" title="翻到哪天的研究日志？" min="2020-01-01" :max="today()" :clearable="false"/><button @click="day=today()">回到今天</button><button :disabled="busy||loading" @click="load">{{loading?'读取中…':'刷新'}}</button></view>
 <view class="daily-report" :class="{celebrating:celebrate}">
 <view class="report-main"><button class="lab-buddy" :class="{awake:report.stamps>0}" aria-label="点一下研究员，换句摸鱼签" @click="fortune=(fortune+1)%fortunes.length"><view class="buddy-face"><text>•</text><text>ᴗ</text><text>•</text></view><text class="buddy-tag">{{report.stamps===2?'吃动双在线':report.stamps?'正在营业':'待投喂'}}</text></button><view class="report-copy"><text class="eyebrow">{{day===today()?'今日':'当日'}}研究报告 · {{day}}</text><text class="report-title">{{report.stamps?report.title:'身体在线，工位离线'}}</text><text class="report-detail">{{report.detail}}</text><view class="report-stamps"><button :class="{lit:report.food}" @click="jumpTo('food')">{{report.food?'✓':'＋'}} 投喂 {{report.food}} 条</button><button :class="{lit:report.exercise}" @click="jumpTo('exercise')">{{report.exercise?'✓':'＋'}} 活动 {{report.exercise}} 条</button></view></view></view>
 <view class="report-footer"><text aria-live="polite">{{fortunes[fortune]}}</text><button @click="fortune=(fortune+1)%fortunes.length">再来一句 ↻</button></view><text class="report-note">亮章只表示记过这类记录，不是健康评分。休息日也欢迎来摸鱼，体重想记再记。</text>
 </view>
 <view class="week-strip"><button v-for="d in week" :key="d.date" :class="{selected:day===d.date}" @click="day=d.date"><text>{{d.caption}}</text><text class="week-symbol">{{d.stamps===2?'✦':d.count?'•':'·'}}</text><text>{{d.count?d.count+'条':'留白'}}</text></button></view>
 <view class="metrics"><view><text>投喂到账</text><text class="number">{{Math.round(intake)}}<text> kcal</text></text><text>已记录的食物</text></view><view><text>活动消耗 · 估算</text><text class="number">{{Math.round(burn)}}<text> kcal</text></text><text>活动了 {{duration}} 分钟</text></view><view><text>体重变化 · 全部记录</text><text class="number">{{change===null?'—':(change>0?'+':'')+(change*2).toFixed(1)}}<text> 斤</text></text><text>{{change===null?'记录两天后查看':weights[0].day+' 至 '+weights[weights.length-1].day}}</text></view></view>
 <text class="note">摄入与运动分别记账；运动消耗包含运动期间静息消耗，并非全天消耗。两数相减不等于热量缺口，体重变化也不等于脂肪变化。</text>
 <view class="columns"><view id="slim-journal" class="card journal"><text class="section">给身体写条动态</text><text v-if="error" class="error" role="alert" selectable>{{error}}</text><text v-if="message" class="success" role="status" aria-live="polite">{{message}}</text><view class="tabs"><button :class="{active:kind==='food'}" @click="kind='food'">🍚 投喂</button><button :class="{active:kind==='exercise'}" @click="kind='exercise'">🚶 活动</button><button :class="{active:kind==='weight'}" @click="kind='weight'">⚖ 体重</button></view>
 <template v-if="kind==='food'"><input v-model="query" class="input" placeholder="搜常见食物，如米饭、鸡蛋"/><view class="chips"><button v-for="f in catalog" :key="f.name" @click="pickFood(f)">{{f.name}}</button><text v-if="!catalog.length" class="note">没找到？在下面自填名称和包装热量。</text></view><view class="editor-aside">胃部客服：报上菜名，本胃安排接待。只记录真正吃下去的，老板画的饼免谈。</view><text class="label">食物名称</text><input v-model="name" :maxlength="80" class="input" placeholder="例如：午饭的米饭"/><view class="fields"><view><text class="label">吃了多少（克）</text><input v-model="grams" type="digit" class="input" placeholder="100"/></view><view><text class="label">每100克热量（千卡）</text><input v-model="rate" type="digit" class="input" placeholder="按包装或食物表填写"/></view></view><text class="note">快捷食物为可食部分的参考均值，可修改。熟米饭与生米不同；油、酱料需另记。包装若标千焦，除以4.184得到千卡；按克称量，饮料也需确认份量。</text></template>
 <template v-else-if="kind==='exercise'"><text class="label">活动项目</text><view class="activity-options" role="group" aria-label="选择活动项目"><button v-for="(item,index) in activityCards" :key="item.title" :class="['activity-card',{chosen:activity===index}]" :aria-pressed="activity===index" @click="activity=index"><text class="activity-icon">{{item.icon}}</text><view class="activity-copy"><text class="activity-title">{{item.title}}</text><text class="activity-detail">{{item.detail}}</text></view><text class="activity-check">{{activity===index?'✓':''}}</text></button></view><view class="editor-aside">{{['溜达归溜达，工资照样拿。记录你已经走过的时间。','步子可以快，工作消息不用回那么快。','跑的是步，不是老板的需求。按实际完成的时间记。','轮子转起来，脑内会议先散场。','伸出去的是胳膊，收回来的是一点松弛。'][activity]}}</view><text class="label">实际活动多久（分钟）</text><input v-model="minutes" type="digit" class="input"/><view class="weight-link"><text class="label">运动时体重（斤）</text><button v-if="latestWeight" @click="useLatestWeight">用最近称重 {{latestWeight.weight*2}} 斤</button></view><input v-model="bodyWeight" type="digit" class="input" placeholder="例如 130"/><text class="note">使用成人活动 MET 估算；强度、体能和设备会影响实际消耗。</text></template>
 <template v-else><text class="label">今天称到的体重（斤）</text><input v-model="bodyWeight" type="digit" class="input" placeholder="例如 130.4"/><text class="note">尽量在相近条件下称重。当天多次打卡，趋势采用最后一条；波动很正常，不用为数字补偿性少吃或加练。</text></template>
 <view v-if="kind!=='weight'" class="preview">{{kind==='food'?'这次投喂约':'这次活动估算'}} <text>{{Number.isFinite(preview)&&preview>=0?Math.round(preview):'—'}}</text> kcal</view><button class="primary" :disabled="busy||!loaded" @click="save">{{busy?'记录中…':kind==='food'?'收下这份快乐':kind==='exercise'?'记下这次活动':'存下体重观察'}}</button>
 </view><view class="card bmi-card"><text class="eyebrow">身体档案 / BMI</text><text class="section">体重不是绩效</text><view class="fields"><view><text class="label">身高（厘米）</text><input v-model="height" type="digit" class="input" placeholder="例如 170"/></view><view><text class="label">体重（斤）</text><input v-model="bodyWeight" type="digit" class="input" placeholder="例如 130"/></view></view><view class="bmi-result"><text class="bmi-number">{{bmiValue===null?'—':bmiValue.toFixed(1)}}</text><text>{{bmiValue===null?'填入身高体重，即时计算':bmiLabel(bmiValue)}}</text></view><view class="scale"><view/><view/><view/><view/></view><text class="note">偏低 &lt;18.5 · 正常 18.5–&lt;24 · 超重 24–&lt;28 · 肥胖 ≥28</text><text class="note">男女成人使用同一公式：（体重斤 ÷ 2）÷ 身高m²。依据中国成人标准，供18岁及以上非孕期成人参考；BMI不能区分肌肉与脂肪，也不作诊断。</text><button class="secondary" :disabled="busy||!loaded" @click="saveProfile">保存身高</button><text class="note">体重请填斤，例如130斤=65公斤。只算 BMI 不会新增体重记录，点击“体重打卡”再保存。数据仅自己可见。</text></view></view>

 <view class="card"><text class="section">身体的慢镜头</text><text class="note">最近14个有记录的日期 · 每天最后一次体重（斤），柱高仅展示相对变化</text><scroll-view scroll-x><view class="chart"><view v-for="e in recentWeights" :key="e.id" class="bar-cell"><text>{{Number((e.weight*2).toFixed(1))}}</text><view class="bar" :style="{height:barHeight(e.weight)}"/><text>{{e.day.slice(5)}}</text></view></view></scroll-view><text v-if="!recentWeights.length" class="empty">研究员尚未上秤。先记录一次，慢慢观察。</text></view>
 <view class="card"><text class="section">{{day}} · 私人研究日志</text><text v-if="!selected.length" class="empty">{{loading?'正在翻日志…':'日志还空着，胃和腿的故事都可以写进来。'}}</text><view v-for="e in shown" :key="e.id" class="entry"><view><text class="entry-name">{{e.kind==='food'?'🍚':e.kind==='exercise'?'🚶':'⚖'}} {{e.name}}</text><text class="note">{{e.kind==='food'?e.quantity+' g · '+e.rate+' kcal/100g':e.kind==='exercise'?e.quantity+' 分钟 · 当时 '+Number((e.weight*2).toFixed(1))+' 斤':'实际称重'}}</text><text class="entry-remark">{{entryRemark(e)}}</text></view><button v-if="e.kind!=='weight'" class="repeat-entry" :disabled="busy" @click="repeat(e)" :aria-label="'再记一次'+e.name">同款再记</button><text class="entry-value">{{e.kind==='weight'?Number((e.weight*2).toFixed(1))+' 斤':Math.round(e.calories)+' kcal'}}</text><button class="delete-entry" :disabled="busy" :aria-label="'删除'+e.name+'记录'" @click="remove(e)"><view class="delete-icon" aria-hidden="true"><view/></view><text>删除</text></button></view><button v-if="shown.length<selected.length" class="secondary" @click="page++">再看20条</button></view>
 <view v-if="deleting" class="delete-backdrop" @click.self="cancelDelete" @keydown="deleteKeys" @touchmove.stop.prevent>
 <view id="slim-delete-dialog" class="delete-dialog" role="dialog" aria-modal="true" aria-labelledby="slim-delete-title" aria-describedby="slim-delete-description" :aria-busy="busy">
 <view class="delete-dialog-top"><text class="eyebrow">研究所 · 撤回一条动态</text><button class="delete-close" :disabled="busy" aria-label="关闭删除确认" @click="cancelDelete">×</button></view>
 <view class="delete-illustration"><view class="delete-icon" aria-hidden="true"><view/></view></view><text id="slim-delete-title" class="delete-title">这条记录，要撤回吗？</text><text id="slim-delete-description" class="delete-description">手滑记错了很正常，研究员也有撤回键。</text>
 <view class="delete-preview"><text class="delete-record-name">{{deleting.kind==='food'?'🍚':deleting.kind==='exercise'?'🚶':'⚖'}} {{deleting.name}}</text><text>{{deleting.day}} · {{deleting.kind==='weight'?Number((deleting.weight*2).toFixed(1))+' 斤':Math.round(deleting.calories)+' kcal'}}</text></view>
 <text class="delete-warning">删除后无法恢复，对应的统计和报告也会更新。</text><text v-if="deleteError" class="delete-modal-error" role="alert">{{deleteError}}</text>
 <view class="delete-actions"><button id="slim-delete-cancel" class="keep-record" :disabled="busy" @click="cancelDelete">先留着</button><button class="confirm-delete" :disabled="busy" @click="confirmDelete">{{busy?'正在撤回…':'确认删除'}}</button></view>
 </view></view>
 <view class="sources"><text>计算依据：国家卫健委《成人体重判定》；2024 Adult Compendium（pacompendium.com）；常见食物为 USDA 等成分表的取整参考值，以实际包装和做法为准。</text><text>这是生活记录，不是减重处方。研究的是好好照顾自己，不是越轻越好。</text></view>
</view>
